import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();

  const menuItems = [
    { name: "Home", action: () => navigate("/") },
    { name: "Profile", action: () => navigate("/profile") },
    { name: "Bookings", action: () => navigate("/booking") },
    { name: "Payment", action: () => navigate("/payment") },
    { name: "Success", action: () => navigate("/success") },
    { name: "Logout", action: () => { localStorage.removeItem("user"); navigate("/login"); } }
  ];

  return (
    <div className="homepage-container">
      {/* Sidebar */}
      <aside className="sidebar">
        {menuItems.map((item, index) => (
          <button key={index} className="sidebar-btn" onClick={item.action}>
            {item.name}
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <div className="welcome-card">
          <h1>Welcome to Parking Slot System!</h1>
          <p>
            Use the sidebar to navigate through the system. Book your parking slots quickly and efficiently.
          </p>
          <button className="start-btn" onClick={() => navigate("/booking")}>
            Start Booking
          </button>
        </div>
      </main>
    </div>
  );
}

export default HomePage;
